/** Neutral surfaces of a style or of a night background (instead of Telegram's blue night / plain day); null = keep the default. */
internal class Neutrals(
    val background: Color,
    val surfaceVariant: Color,
    val onSurfaceVariant: Color,
    val topBar: Color,
    val onTopBar: Color?,
    val onTopBarMuted: Color,
    val drawerHeader: Color?,
    val archive: Color,
    val chatBackground: Color,
    val bubbleIn: Color,
    val timeIn: Color,
    val text: Color?,
    val service: Color?,
    val divider: Color?,
    val outlineVariant: Color,
    val containerLowest: Color,
    val container: Color,
    val containerHighest: Color,
    val online: Color?,
)

/**
 * The style's surfaces by day, the [night] background's by night (each style has its own blue-grey and graphite); Tinted Glass has
 * one set per [accent]. null = the default Telegram look. (Dynamic colours drop all of them in the caller.)
 */
internal fun neutralsOf(style: TatrakStyle, dark: Boolean, night: NightBackground, accent: Accent): Neutrals? =
    when (style) {
        TatrakStyle.TELEGRAM -> pick(telegram, dark, night)
        TatrakStyle.SLATE_SEA -> pick(slate, dark, night)
        TatrakStyle.GLASS -> pick(glass, dark, night)
        TatrakStyle.WARM -> pick(warm, dark, night)
        TatrakStyle.TINTED -> pick(tinted.getValue(accent), dark, night)
    }

/** [set] = day, blue-grey, graphite, AMOLED. */
private fun pick(set: Array<Neutrals?>, dark: Boolean, night: NightBackground): Neutrals? =
    if (!dark) set[0]
    else when (night) {
        NightBackground.BLUE_GREY -> set[1]
        NightBackground.GRAPHITE -> set[2]
        NightBackground.AMOLED -> set[3]
    }

